-- ============================================================================
-- Green Dog Ops — 0176 ezyVet extra reports (payments, receivables, close,
-- appointments, clinical, inventory)
-- ----------------------------------------------------------------------------
-- GENERATED by scripts/gen_report_migration.mts from src/lib/reporting/
-- report-specs.ts — regenerate rather than hand-editing, or the parser and the
-- schema will drift apart.
--
-- One table per ezyVet Report Center report pulled by agent/extra-reports.mjs.
-- Every table shares three ingest columns:
--   snapshot_date  the target day of the pull that produced the row
--   period_start   \
--   period_end     /  the From/To window that was requested
--
-- Reports with a natural key are upserted; the rest are rebuilt for the window
-- they cover, so re-running a day is idempotent either way.
-- ============================================================================
set search_path = greendogops, public;


-- ---------------------------------------------------------------------------
-- Payments — ezyVet report "Payment Summary"
-- Every payment taken, by method and hospital — what was actually COLLECTED.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_payment (
  id                    uuid primary key default gen_random_uuid(),
  payment_date          date,
  paid_at               timestamptz,
  payment_number        bigint,
  division              text,
  customer_code         text,
  customer              text,
  amount                numeric,
  surcharge             numeric,
  card_brand            text,
  integrated_surcharge  numeric,
  created_by            text,
  modified_by           text,
  payment_method        text,
  location_key          text,

  snapshot_date         date not null,
  period_start          date,
  period_end            date,
  created_at            timestamptz not null default now()
);
create index if not exists ezyvet_payment_date_idx
  on greendogops.ezyvet_payment (payment_date);
create index if not exists ezyvet_payment_snapshot_idx
  on greendogops.ezyvet_payment (snapshot_date);
create index if not exists ezyvet_payment_location_idx
  on greendogops.ezyvet_payment (location_key);
comment on table greendogops.ezyvet_payment is
  'One row per payment received, from the ezyVet Payment Summary report. payment_method is the section the payment was listed under (Visa, Cash, CareCredit, Remote Payment...), card_brand the specific card. This is CASH COLLECTED and is NOT the same as revenue billed (ezyvet_invoice_line): a payment may settle an older invoice, and an invoice may go unpaid. Use this for deposits, payment-mix and collections questions.';

-- ---------------------------------------------------------------------------
-- Payment Allocations — ezyVet report "Payment Allocations To Divisions"
-- How each payment was split across hospitals/divisions.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_payment_allocation (
  id                    uuid primary key default gen_random_uuid(),
  allocation_date       date,
  payment_number        bigint,
  payment_division      text,
  client                text,
  invoice_number        bigint,
  division              text,
  divisional_amount     numeric,
  total_for_invoice     numeric,
  total_payment_amount  numeric,
  location_key          text,

  snapshot_date         date not null,
  period_start          date,
  period_end            date,
  created_at            timestamptz not null default now()
);
create index if not exists ezyvet_payment_allocation_date_idx
  on greendogops.ezyvet_payment_allocation (allocation_date);
create index if not exists ezyvet_payment_allocation_snapshot_idx
  on greendogops.ezyvet_payment_allocation (snapshot_date);
create index if not exists ezyvet_payment_allocation_location_idx
  on greendogops.ezyvet_payment_allocation (location_key);
comment on table greendogops.ezyvet_payment_allocation is
  'One row per payment-to-invoice allocation. Shows which division earned the money when a payment taken at one hospital settles another''s invoice. divisional_amount is that division''s share; total_payment_amount repeats the whole payment, so NEVER sum total_payment_amount across rows.';

-- ---------------------------------------------------------------------------
-- Aged Receivables — ezyVet report "Aged Receivables"
-- Client accounts receivable, aged into 30/60/90+ day buckets.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_aged_receivable (
  id                     uuid primary key default gen_random_uuid(),
  contact_code           text,
  title                  text,
  client                 text,
  first_name             text,
  contact_tags           text,
  email                  text,
  total_due              numeric,
  last_30_days_payments  numeric,
  bucket_current         numeric,
  bucket_30              numeric,
  bucket_60              numeric,
  bucket_90_plus         numeric,

  snapshot_date          date not null,
  period_start           date,
  period_end             date,
  created_at             timestamptz not null default now()
);
create unique index if not exists ezyvet_aged_receivable_key_idx
  on greendogops.ezyvet_aged_receivable (contact_code, snapshot_date);
create index if not exists ezyvet_aged_receivable_snapshot_idx
  on greendogops.ezyvet_aged_receivable (snapshot_date);
comment on table greendogops.ezyvet_aged_receivable is
  'Daily snapshot of client A/R (one row per client per snapshot_date, so the aging can be trended). ezyVet names the aging columns after calendar months, which move every month, so they are stored positionally: bucket_current is the newest month, then bucket_30 / bucket_60 / bucket_90_plus going further back. total_due is the balance owed. Join to ezyvet_contact on contact_code.';

-- ---------------------------------------------------------------------------
-- End of Day Totals — ezyVet report "End of Day Totals"
-- Daily close: pending vs approved invoices, payments by type, debtor balances.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_end_of_day (
  id              uuid primary key default gen_random_uuid(),
  metric          text,
  amount          numeric,

  snapshot_date   date not null,
  period_start    date,
  period_end      date,
  created_at      timestamptz not null default now()
);
create unique index if not exists ezyvet_end_of_day_key_idx
  on greendogops.ezyvet_end_of_day (metric, snapshot_date);
create index if not exists ezyvet_end_of_day_snapshot_idx
  on greendogops.ezyvet_end_of_day (snapshot_date);
comment on table greendogops.ezyvet_end_of_day is
  'Long-form daily close figures — one row per metric per day. Metrics include Pending Invoices, Approved Invoices, Opening Debtors, Closing Debtors, Payments Received, plus one row per payment method. Query with metric ILIKE, and remember amounts are practice-wide for that day.';

