  pet_name                text,
  pet_insurance_supplier  text,
  pet_insurance_number    text,
  invoice_department      text,
  invoice_comments        text,
  payment_terms           text,
  location_key            text,

  snapshot_date           date not null,
  period_start            date,
  period_end              date,
  created_at              timestamptz not null default now()
