-- ---------------------------------------------------------------------------
-- Staff Sales & Gross Profit — ezyVet report "Staff Sales"
-- Per-invoice turnover and GROSS PROFIT credited to the staff member who raised it.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_staff_sale (
  id                uuid primary key default gen_random_uuid(),
  invoice_number    bigint,
  invoiced_at       timestamptz,
  invoice_date      date,
  turnover          numeric,
  gross_profit      numeric,
  gross_profit_pct  numeric,
  staff_member      text,

  snapshot_date     date not null,
  period_start      date,
  period_end        date,
  created_at        timestamptz not null default now()
);
create index if not exists ezyvet_staff_sale_date_idx
  on greendogops.ezyvet_staff_sale (invoice_date);
create index if not exists ezyvet_staff_sale_snapshot_idx
  on greendogops.ezyvet_staff_sale (snapshot_date);
comment on table greendogops.ezyvet_staff_sale is
  'One row per invoice per staff member, with turnover and gross profit in dollars and percent. This is the ONLY source of margin in the warehouse — ezyvet_invoice_line carries revenue but no cost. Note gross profit only counts products that have a cost price and markup. staff_member is the SALESPERSON who raised the invoice, not the case-owning doctor.';

