  mins_admit_for_surgery  numeric,
  mins_in_hospital        numeric,
  mins_in_discharge       numeric,
  mins_awaiting_collect   numeric,
  mins_departed           numeric,
  mins_interim_report     numeric,
  mins_referral_done      numeric,
  mins_complete           numeric,
  time_to_complete        text,
  mins_to_complete        numeric,
  location_key            text,

  snapshot_date           date not null,
  period_start            date,
  period_end              date,
  created_at              timestamptz not null default now()
);
create index if not exists ezyvet_appointment_status_date_idx
  on greendogops.ezyvet_appointment_status (appt_date);
create index if not exists ezyvet_appointment_status_snapshot_idx
  on greendogops.ezyvet_appointment_status (snapshot_date);
create index if not exists ezyvet_appointment_status_location_idx
  on greendogops.ezyvet_appointment_status (location_key);
comment on table greendogops.ezyvet_appointment_status is
  'One row per appointment, with the MINUTES it spent in each ezyVet status (mins_in_waiting_room, mins_in_consultation, mins_in_hospital...) and mins_to_complete. This is the operational counterpart to the agenda counts: use it for wait times, room/doctor throughput and how long visit types really take. time_to_complete reads ''Not Complete'' (and mins_to_complete is null) when the appointment was never finished, which is common — filter those out before averaging.';

