  on greendogops.ezyvet_appointment_type_stat (snapshot_date);
create index if not exists ezyvet_appointment_type_stat_location_idx
  on greendogops.ezyvet_appointment_type_stat (location_key);
comment on table greendogops.ezyvet_appointment_type_stat is
  'Aggregated per appointment type and division for the pulled window: how many were booked and the average and total minutes. Use this to size scheduling templates against how long visits actually take.';

-- ---------------------------------------------------------------------------
-- Unbilled Consults — ezyVet report "Unbilled Consult Appointments"
