  'Consults that happened but were never invoiced: the daily missed-revenue worklist. Re-read over a rolling two-week window, so a consult that gets invoiced later simply drops out of the table.';

-- ---------------------------------------------------------------------------
-- Estimates — ezyVet report "Estimate Status"
-- Every estimate and its stage — the quote-to-acceptance funnel.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_estimate (
  id                          uuid primary key default gen_random_uuid(),
  date_sent                   date,
  date_sent_raw               text,
  originator                  text,
  estimate_number             bigint,
  estimate_name               text,
  customer_number             text,
  customer_name               text,
