create index if not exists ezyvet_estimate_snapshot_idx
  on greendogops.ezyvet_estimate (snapshot_date);
comment on table greendogops.ezyvet_estimate is
  'One row per estimate with its status (Created / Sent / Accepted / Declined), value and originating doctor. Conversion rate = accepted value over total value. date_sent is null while the estimate is unsent (date_sent_raw then reads ''Not Sent''). Re-read on a rolling window and upserted, since estimates change status days after they are written.';

-- ---------------------------------------------------------------------------
-- Consult Metrics — ezyVet report "Consult Metrics"
