create index if not exists ezyvet_consult_metric_date_idx
  on greendogops.ezyvet_consult_metric (created_date);
create index if not exists ezyvet_consult_metric_snapshot_idx
  on greendogops.ezyvet_consult_metric (snapshot_date);
comment on table greendogops.ezyvet_consult_metric is
  'One row per clinical record: the case owner, the pet (species, breed, weight, date of birth) and the MASTER and PRESENTING PROBLEMS. This is the only source of what we actually treat, so use it for case-mix, caseload-by-condition and per-doctor clinical questions. Problems are free text and may list several separated by commas, so match with ILIKE.';

