  next_date              date,
  send_reminder          boolean,
  is_historical          boolean,
  annual_health_product  text,
  event                  text,

  snapshot_date          date not null,
  period_start           date,
  period_end             date,
  created_at             timestamptz not null default now()
);
create unique index if not exists ezyvet_vaccination_key_idx
  on greendogops.ezyvet_vaccination (vaccination_id);
create index if not exists ezyvet_vaccination_date_idx
  on greendogops.ezyvet_vaccination (vaccination_date);
create index if not exists ezyvet_vaccination_snapshot_idx
  on greendogops.ezyvet_vaccination (snapshot_date);
comment on table greendogops.ezyvet_vaccination is
  'One row per vaccination administered: product, quantity, the vet who gave it, the date, and next_date for the reminder. is_historical marks vaccinations recorded from an outside clinic rather than given here.';

-- ---------------------------------------------------------------------------
-- Standard of Care Overdue — ezyVet report "SOC Overdue with Upcoming Appointments"
-- Pets with overdue standard-of-care items who already have an appointment booked.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_soc_overdue (
  id                     uuid primary key default gen_random_uuid(),
  animal_number          text,
  animal_name            text,
  species                text,
  breed                  text,
  owner_first_name       text,
  owner_last_name        text,
  phone_numbers          text,
  mobile_numbers         text,
  email_addresses        text,
  soc_treatment          text,
  soc_type               text,
  soc_due_date           date,
  days_overdue           bigint,
  last_fulfilled_date    date,
  appt_date              date,
  days_until_appt        bigint,
  appt_duration_minutes  bigint,
  appt_reason            text,
  appt_status            text,
  appt_type              text,
  soc_created_date       date,
  department             text,
  location_key           text,

  snapshot_date          date not null,
  period_start           date,
  period_end             date,
  created_at             timestamptz not null default now()
);
create index if not exists ezyvet_soc_overdue_snapshot_idx
  on greendogops.ezyvet_soc_overdue (snapshot_date);
create index if not exists ezyvet_soc_overdue_location_idx
  on greendogops.ezyvet_soc_overdue (location_key);
comment on table greendogops.ezyvet_soc_overdue is
  'The pre-visit preparation worklist: pets with an overdue standard-of-care item (vaccine, test, treatment) AND an upcoming appointment, so the team can add it before the visit. days_overdue is how late the item is, days_until_appt how soon they are coming in. Daily snapshot — filter to the latest snapshot_date, and note the same pet appears once per overdue item.';

-- ---------------------------------------------------------------------------
-- Wellness Plan Use — ezyVet report "Wellness Plan Use"
-- Membership benefit utilisation: what is allocated, used and remaining.
