  customer_code    text,
  customer_name    text,
  pet_code         text,
  pet_name         text,
  plan             text,
  department       text,
  term_start_date  date,
  benefit          text,
  benefit_type     text,
  saved            numeric,
  allocated        numeric,
  used             numeric,
  available        numeric,
  location_key     text,

  snapshot_date    date not null,
  period_start     date,
  period_end       date,
  created_at       timestamptz not null default now()
);
