  on greendogops.ezyvet_wellness_plan_use (unique_id, snapshot_date);
create index if not exists ezyvet_wellness_plan_use_snapshot_idx
  on greendogops.ezyvet_wellness_plan_use (snapshot_date);
create index if not exists ezyvet_wellness_plan_use_location_idx
  on greendogops.ezyvet_wellness_plan_use (location_key);
comment on table greendogops.ezyvet_wellness_plan_use is
  'One row per pet per plan benefit per snapshot: allocated, used and available. Unused ''available'' benefits are the practice''s outstanding liability and the reason to recall the client. Large table (~20k rows per snapshot), so always filter to one snapshot_date and aggregate.';

-- ---------------------------------------------------------------------------
-- Inventory Value — ezyVet report "Inventory Value"
-- Stock on hand and the dollars tied up in it, per product per day.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_inventory_value (
  id                      uuid primary key default gen_random_uuid(),
  product_code            text,
  product_name            text,
  product_group           text,
  current_unit_cost       numeric,
