  period_start            date,
  period_end              date,
  created_at              timestamptz not null default now()
);
create unique index if not exists ezyvet_inventory_value_key_idx
  on greendogops.ezyvet_inventory_value (product_code, snapshot_date);
create index if not exists ezyvet_inventory_value_snapshot_idx
  on greendogops.ezyvet_inventory_value (snapshot_date);
comment on table greendogops.ezyvet_inventory_value is
  'Daily snapshot of stocked products: quantity in inventory, current and weighted-average unit cost, and total value. Trend total_inventory_value by snapshot_date for stock levels over time. Negative quantities are real in ezyVet (items sold that were never received) and flag count errors.';

-- ---------------------------------------------------------------------------
-- Expiring Inventory — ezyVet report "Expiring Inventory"
-- Batches expiring in the next six months — waste prevention worklist.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_expiring_inventory (
  id                    uuid primary key default gen_random_uuid(),
  product_code          text,
  product_name          text,
  supplier_name         text,
