  on greendogops.ezyvet_expiring_inventory (snapshot_date);
comment on table greendogops.ezyvet_expiring_inventory is
  'Product batches with an expiry date inside the look-ahead window, with quantity and the cost at risk. Daily snapshot; use the latest snapshot_date and order by expiry_date to work the list.';

-- ---------------------------------------------------------------------------
-- Expired Inventory — ezyVet report "Expired Inventory"
-- Batches already past their expiry date that are still in stock.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_expired_inventory (
  id              uuid primary key default gen_random_uuid(),
  product_code    text,
  product_name    text,
