);
create index if not exists ezyvet_expired_inventory_snapshot_idx
  on greendogops.ezyvet_expired_inventory (snapshot_date);
comment on table greendogops.ezyvet_expired_inventory is
  'Stock that has already expired and should be pulled and written off. Daily snapshot — anything appearing here is a live problem.';

-- ---------------------------------------------------------------------------
-- Inventory Ordering — ezyVet report "Inventory Ordering"
-- Reorder worklist with stock turns: what to order and how fast it moves.
-- ---------------------------------------------------------------------------
create table if not exists greendogops.ezyvet_inventory_ordering (
  id                   uuid primary key default gen_random_uuid(),
  product_code         text,
  product_name         text,
  in_inventory         numeric,
  available            numeric,
  ordered              numeric,
  receipting           numeric,
