create index if not exists ezyvet_inventory_ordering_snapshot_idx
  on greendogops.ezyvet_inventory_ordering (snapshot_date);
comment on table greendogops.ezyvet_inventory_ordering is
  'Daily snapshot of the ordering position per product: in inventory, available, on order, receipting, short, and to_order, plus inventory turns for last month, the last 12 months and the monthly average. to_order > 0 is the buy list; low turns with high stock is dead money.';

-- ---------------------------------------------------------------------------
